"""Test profile YAML generated by MappingWizard logic against backend BankProfile and API."""

import pytest
from fastapi.testclient import TestClient

from billapp.app import create_app
from billapp.importers.base import FileProbe
from billapp.importers.profile_engine import BankProfile, ProfileImporter


def generate_test_yaml(
    profile_id: str,
    name: str,
    bank: str,
    account_kind: str,
    header_row_index: int,
    data_start_row_index: int,
    amount_mode: str,
    field_map: dict,
    split_expense: str = "",
    split_income: str = "",
    flag_col: str = "",
    flag_expense_val: str = "支出",
    flag_income_val: str = "收入",
) -> str:
    mapped_kind = "credit" if account_kind in ("bank_credit", "credit") else "debit"
    header_idx = max(0, header_row_index - 1)
    data_start_offset = max(1, data_start_row_index - header_row_index)

    lines = [
        f'id: "{profile_id}"',
        f'name: "{name}"',
        f'bank: "{bank}"',
        f'account_kind: "{mapped_kind}"',
        'file_type: "auto"',
        'currency: "CNY"',
        'table_detection:',
        f"  header_row_index: {header_idx}",
        f"  data_start_offset: {data_start_offset}",
        "column_mapping:",
        f'  date: "{field_map.get("txn_time", "")}"',
    ]

    if amount_mode == "signed":
        lines.append(f'  amount: "{field_map.get("amount", "")}"')
    elif amount_mode == "split":
        lines.append(f'  expense_amount: "{split_expense}"')
        lines.append(f'  income_amount: "{split_income}"')
    elif amount_mode == "flag":
        lines.append(f'  amount: "{field_map.get("amount", "")}"')
        lines.append(f'  direction: "{flag_col}"')

    lines.append(f'  counterparty: "{field_map.get("counterparty", "")}"')
    lines.append(f'  description: "{field_map.get("description", "")}"')
    lines.append(f'  channel: "{field_map.get("channel", "")}"')
    if field_map.get("card_tail"):
        lines.append(f'  card_tail: "{field_map.get("card_tail", "")}"')

    lines.append("amount_mode:")
    if amount_mode == "signed":
        lines.append('  type: "signed"')
        lines.append(f'  amount_col: "{field_map.get("amount", "")}"')
    elif amount_mode == "split":
        lines.append('  type: "split"')
        lines.append(f'  expense_col: "{split_expense}"')
        lines.append(f'  income_col: "{split_income}"')
    elif amount_mode == "flag":
        lines.append('  type: "flag"')
        lines.append(f'  amount_col: "{field_map.get("amount", "")}"')
        lines.append(f'  direction_col: "{flag_col}"')
        lines.append(f'  flag_col: "{flag_col}"')
        lines.append("  flag_mapping:")
        lines.append(f'    "{flag_expense_val}": "expense"')
        lines.append(f'    "{flag_income_val}": "income"')

    return "\n".join(lines)


def test_signed_yaml_parsing():
    yaml_str = generate_test_yaml(
        profile_id="test_signed_1",
        name="Signed Profile",
        bank="招商银行",
        account_kind="bank_debit",
        header_row_index=1,
        data_start_row_index=2,
        amount_mode="signed",
        field_map={
            "txn_time": "交易时间",
            "amount": "金额",
            "counterparty": "对方",
            "description": "摘要",
            "channel": "方式",
        },
    )
    p = BankProfile.from_yaml(yaml_str)
    assert p.id == "test_signed_1"
    assert p.account_kind == "debit"
    assert p.amount_mode.type == "signed"
    assert p.amount_mode.amount_col == "金额"
    assert p.column_mapping.date.header == "交易时间"
    assert p.column_mapping.amount.header == "金额"


def test_split_yaml_parsing():
    yaml_str = generate_test_yaml(
        profile_id="test_split_1",
        name="Split Profile",
        bank="建设银行",
        account_kind="bank_credit",
        header_row_index=1,
        data_start_row_index=2,
        amount_mode="split",
        field_map={
            "txn_time": "交易日期",
            "counterparty": "对方账户",
            "description": "摘要",
        },
        split_expense="支出金额",
        split_income="收入金额",
    )
    p = BankProfile.from_yaml(yaml_str)
    assert p.id == "test_split_1"
    assert p.account_kind == "credit"
    assert p.amount_mode.type == "split"
    assert p.amount_mode.expense_col == "支出金额"
    assert p.amount_mode.income_col == "收入金额"
    assert p.column_mapping.expense_amount.header == "支出金额"
    assert p.column_mapping.income_amount.header == "收入金额"


def test_flag_yaml_parsing():
    yaml_str = generate_test_yaml(
        profile_id="test_flag_1",
        name="Flag Profile",
        bank="平安银行",
        account_kind="bank_debit",
        header_row_index=1,
        data_start_row_index=2,
        amount_mode="flag",
        field_map={
            "txn_time": "交易时间",
            "amount": "交易金额",
            "counterparty": "商户",
            "description": "说明",
        },
        flag_col="收/支",
        flag_expense_val="支出",
        flag_income_val="收入",
    )
    p = BankProfile.from_yaml(yaml_str)
    assert p.id == "test_flag_1"
    assert p.account_kind == "debit"
    assert p.amount_mode.type == "flag"
    assert p.amount_mode.amount_col == "交易金额"
    assert p.amount_mode.direction_col == "收/支"
    assert p.amount_mode.flag_mapping == {"支出": "expense", "收入": "income"}
    assert p.column_mapping.direction.header == "收/支"


def test_api_create_profile_end_to_end(tmp_path):
    db_file = tmp_path / "test_api.db"
    app = create_app(db_path=db_file)
    with TestClient(app) as client:
        for mode in ("signed", "split", "flag"):
            pid = f"test_{mode}_profile"
            yaml_content = generate_test_yaml(
                profile_id=pid,
                name=f"{mode.title()} Bank Profile",
                bank="测试银行",
                account_kind="bank_debit" if mode != "split" else "bank_credit",
                header_row_index=1,
                data_start_row_index=2,
                amount_mode=mode,
                field_map={
                    "txn_time": "交易时间",
                    "amount": "金额",
                    "counterparty": "对方",
                    "description": "说明",
                },
                split_expense="支出",
                split_income="收入",
                flag_col="收支标志",
            )
            res = client.post(
                "/api/profiles",
                json={
                    "id": pid,
                    "name": f"{mode.title()} Bank Profile",
                    "yaml_content": yaml_content,
                },
            )
            assert res.status_code == 201, f"Failed for mode {mode}: {res.text}"
            data = res.json()
            assert data["id"] == pid
            assert data["account_kind"] in ("debit", "credit")

            # Check GET /api/profiles/{id}
            get_res = client.get(f"/api/profiles/{pid}")
            assert get_res.status_code == 200
            assert get_res.json()["name"] == f"{mode.title()} Bank Profile"
